import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid inputs', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-03-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
});

test('createInvoice includes product details from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: undefined,
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns DATE_INVALID for incorrect format', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '15/03/2024',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result1, { ok: false, error: 'DATE_INVALID' });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-3-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result2, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns DATE_INVALID for non-existent date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: undefined,
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice validates all lines and fails on first error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice handles various VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  };

  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal handles single quantity', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal handles zero price', () => {
  const line = { qty: 10, unitPrice: 0 };
  assert.equal(lineTotal(line), 0);
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 2, unitPrice: 8500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 17000);
  assert.equal(totals.total, 47500 + 17000);
});

test('invoiceTotals returns equal subtotal and total for now', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 6000 },
      { qty: 4, unitPrice: 7250 },
      { qty: 1, unitPrice: 245000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, totals.total);
  assert.equal(totals.subtotal, 18000 + 29000 + 245000);
});

test('invoiceTotals handles single line', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 9500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 76000);
  assert.equal(totals.total, 76000);
});

test('invoiceTotals handles empty lines array', () => {
  const invoice = {
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with invoice created by createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // DEV-HOUR: 9500 * 5 = 47500
  // DES-HOUR: 8500 * 2 = 17000
  // Total: 64500
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.total, 64500);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 2 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].qty, 2);
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('addLine preserves other lines when adding existing SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 1 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 6);
  assert.equal(result.value.lines[1].qty, 2);
});

test('addLine returns QTY_INVALID for non-positive quantity', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 0 });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('addLine returns QTY_INVALID for non-integer quantity', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 1.5 });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('addLine returns UNKNOWN_SKU for invalid SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'INVALID-SKU', qty: 1 });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine returns NOT_DRAFT if invoice status is not draft', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const nonDraftInvoice = { ...invoiceResult.value, status: 'sent' };
  const result = addLine(nonDraftInvoice, { sku: 'DES-HOUR', qty: 1 });

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'DES-HOUR', qty: 2 });

  assert.deepEqual(invoice, invoiceCopy);
});

test('removeLine removes a line from an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const result = removeLine(invoiceResult.value, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine removes from middle of lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const result = removeLine(invoiceResult.value, 'DES-HOUR');

