  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR is 9500 cents per unit
  // subtotal = 95000
  // discount = 9500
  // total = 85500
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 85500);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // 9500*5=47500, discount 4750
      { sku: 'DES-HOUR', qty: 2, discountPercent: 20 }, // 8500*2=17000, discount 3400
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // Total subtotal: 47500 + 17000 = 64500
  // Total discount: 4750 + 3400 = 8150
  // Total: 64500 - 8150 = 56350
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 8150);
  assert.equal(totals.total, 56350);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000, // 1000 cents = €10
        vatRate: 21,
        discountPercent: 150, // Invalid but we manually create for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount would be 1000 * 150 / 100 = 15000, but gets clamped
  // Actually no - discount calculation doesn't clamp, the total clamps
  // discount = 15000
  // total = max(0, 1000 - 15000) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 15000);
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 2, discountPercent: 15 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 2 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 0);
});

test('addLine returns DISCOUNT_INVALID if discountPercent is invalid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 2, discountPercent: 150 });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DISCOUNT_INVALID');
});

